import{_ as e,o as d,c as o,a6 as a}from"./chunks/framework.DIp0zHSV.js";const g=JSON.parse('{"title":"Themes","description":"","frontmatter":{},"headers":[],"relativePath":"core/themes/index.md","filePath":"core/themes/index.md","lastUpdated":1792162559000}'),c={name:"core/themes/index.md"};function r(l,t,s,n,h,i){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="themes" tabindex="-1">Themes <a class="header-anchor" href="#themes" aria-label="Permalink to &quot;Themes&quot;">​</a></h1><p>To complement the HA-LCARS system theme - LCARdS adds a token-based theme system for its cards. Instead of hardcoding colours and other default settings, we can reference named tokens that the active theme resolves at runtime. Currently the <code>lcards-default</code> theme is loaded at startup, but in the future new theme packs can be added to easily change the look of all the cards.</p><hr><h2 id="built-in-themes" tabindex="-1">Built-in Themes <a class="header-anchor" href="#built-in-themes" aria-label="Permalink to &quot;Built-in Themes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Theme</th><th>Description</th></tr></thead><tbody><tr><td><code>lcards-default</code></td><td>Standard LCARS look</td></tr></tbody></table><p>Themes are provided by content packs. See the <a href="./../../configuration/">Config Panel</a> Pack Explorer to view all the tokens that theme provides.</p><hr><h2 id="using-theme-tokens" tabindex="-1">Using Theme Tokens <a class="header-anchor" href="#using-theme-tokens" aria-label="Permalink to &quot;Using Theme Tokens&quot;">​</a></h2><p>Reference a token in card configs, such as a colour or size field using <code>{theme:token.path}</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">style</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  border</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{theme:colors.ui.primary}&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  card</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      background</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{theme:colors.ui.primary}&quot;</span></span></code></pre></div><hr><h2 id="token-namespaces" tabindex="-1">Token Namespaces <a class="header-anchor" href="#token-namespaces" aria-label="Permalink to &quot;Token Namespaces&quot;">​</a></h2><p>Tokens are organized into namespaces. Browse all available tokens in the <a href="./../../configuration/#theme-studio">Config Panel</a> Theme Studio; a card editor&#39;s Main Engineering &gt; Theme tab lists the ones that card uses.</p><h3 id="example-colors-ui" tabindex="-1">Example: <code>colors.ui.*</code> <a class="header-anchor" href="#example-colors-ui" aria-label="Permalink to &quot;Example: \`colors.ui.*\`&quot;">​</a></h3><p>Semantic colours that map to UI roles. In the default theme, prefer HA-LCARS theme colours but provide LCARdS fallbacks:</p><table tabindex="0"><thead><tr><th>Token</th><th><code>lcards-default</code> value</th></tr></thead><tbody><tr><td><code>colors.ui.primary</code></td><td><code>var(--lcars-ui-primary, var(--lcards-gray-medium))</code></td></tr><tr><td><code>colors.ui.secondary</code></td><td><code>var(--lcars-ui-secondary, var(--lcards-gray-medium-light))</code></td></tr><tr><td><code>colors.ui.tertiary</code></td><td><code>var(--lcars-ui-tertiary, var(--lcards-orange-medium-dark))</code></td></tr><tr><td><code>colors.ui.quaternary</code></td><td><code>var(--lcars-ui-quaternary, var(--lcards-gray-dark))</code></td></tr></tbody></table><hr><h2 id="lcards-css-colour-palette" tabindex="-1">LCARdS CSS Colour Palette <a class="header-anchor" href="#lcards-css-colour-palette" aria-label="Permalink to &quot;LCARdS CSS Colour Palette&quot;">​</a></h2><p>LCARdS injects a complete set of <code>--lcards-&lt;colour&gt;-&lt;shade&gt;</code> CSS variables at startup. These colours can be used anywhere and do not need to be in your HA-LCARS theme file.</p><blockquote><p><strong>Note:</strong> Colours shown are the <strong>green_alert (normal) mode</strong> baseline values. When an alert mode is active (e.g. <code>red_alert</code>, <code>blue_alert</code>), all variables are HSL-transformed automatically; you never need to change your references.</p></blockquote><hr><h3 id="🟠-orange" tabindex="-1">🟠 Orange <a class="header-anchor" href="#🟠-orange" aria-label="Permalink to &quot;🟠 Orange&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Swatch</th><th>CSS Variable</th><th>Hex</th><th>Notes</th></tr></thead><tbody><tr><td><img src="https://placehold.co/20x20/d91604/d91604.png" alt=""></td><td><code>--lcards-orange-darkest</code> / <code>-05</code></td><td><code>#d91604</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/e01808/e01808.png" alt=""></td><td><code>--lcards-orange-10</code></td><td><code>#e01808</code></td><td>Computed (interpolated)</td></tr><tr><td><img src="https://placehold.co/20x20/ef1d10/ef1d10.png" alt=""></td><td><code>--lcards-orange-dark</code> / <code>-20</code></td><td><code>#ef1d10</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/e7442a/e7442a.png" alt=""></td><td><code>--lcards-orange-medium-dark</code> / <code>-30</code></td><td><code>#e7442a</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/ff6753/ff6753.png" alt=""></td><td><code>--lcards-orange</code> / <code>-medium</code> / <code>-40</code></td><td><code>#ff6753</code></td><td>Canon (base orange)</td></tr><tr><td><img src="https://placehold.co/20x20/ff715d/ff715d.png" alt=""></td><td><code>--lcards-orange-50</code></td><td><code>#ff715d</code></td><td>Computed (interpolated)</td></tr><tr><td><img src="https://placehold.co/20x20/ff7b66/ff7b66.png" alt=""></td><td><code>--lcards-orange-60</code></td><td><code>#ff7b66</code></td><td>Computed (interpolated)</td></tr><tr><td><img src="https://placehold.co/20x20/ff8470/ff8470.png" alt=""></td><td><code>--lcards-orange-medium-light</code> / <code>-70</code></td><td><code>#ff8470</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/ff977b/ff977b.png" alt=""></td><td><code>--lcards-orange-light</code> / <code>-80</code></td><td><code>#ff977b</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/ffb399/ffb399.png" alt=""></td><td><code>--lcards-orange-lightest</code> / <code>-90</code></td><td><code>#ffb399</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/ffceb3/ffceb3.png" alt=""></td><td><code>--lcards-orange-95</code></td><td><code>#ffceb3</code></td><td>Computed (extrapolated)</td></tr></tbody></table><hr><h3 id="⚫-gray" tabindex="-1">⚫ Gray <a class="header-anchor" href="#⚫-gray" aria-label="Permalink to &quot;⚫ Gray&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Swatch</th><th>CSS Variable</th><th>Hex</th><th>Notes</th></tr></thead><tbody><tr><td><img src="https://placehold.co/20x20/1e2229/1e2229.png" alt=""></td><td><code>--lcards-gray-darkest</code> / <code>-05</code></td><td><code>#1e2229</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/232933/232933.png" alt=""></td><td><code>--lcards-gray-10</code></td><td><code>#232933</code></td><td>Computed (interpolated)</td></tr><tr><td><img src="https://placehold.co/20x20/2f3749/2f3749.png" alt=""></td><td><code>--lcards-gray-dark</code> / <code>-20</code></td><td><code>#2f3749</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/52596e/52596e.png" alt=""></td><td><code>--lcards-gray-medium-dark</code> / <code>-30</code></td><td><code>#52596e</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/6d748c/6d748c.png" alt=""></td><td><code>--lcards-gray</code> / <code>-medium</code> / <code>-40</code></td><td><code>#6d748c</code></td><td>Canon (base gray)</td></tr><tr><td><img src="https://placehold.co/20x20/7d849b/7d849b.png" alt=""></td><td><code>--lcards-gray-50</code></td><td><code>#7d849b</code></td><td>Computed (interpolated)</td></tr><tr><td><img src="https://placehold.co/20x20/8d94aa/8d94aa.png" alt=""></td><td><code>--lcards-gray-60</code></td><td><code>#8d94aa</code></td><td>Computed (interpolated)</td></tr><tr><td><img src="https://placehold.co/20x20/9ea5ba/9ea5ba.png" alt=""></td><td><code>--lcards-gray-medium-light</code> / <code>-70</code></td><td><code>#9ea5ba</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/d2d5df/d2d5df.png" alt=""></td><td><code>--lcards-gray-light</code> / <code>-80</code></td><td><code>#d2d5df</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/f3f4f7/f3f4f7.png" alt=""></td><td><code>--lcards-gray-lightest</code> / <code>-90</code></td><td><code>#f3f4f7</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/f8f9fc/f8f9fc.png" alt=""></td><td><code>--lcards-gray-95</code></td><td><code>#f8f9fc</code></td><td>Computed (extrapolated)</td></tr><tr><td><img src="https://placehold.co/20x20/dfe1e8/dfe1e8.png" alt=""></td><td><code>--lcards-moonlight</code></td><td><code>#dfe1e8</code></td><td>Near-white; used for text/labels (not part of the 11-stop scale)</td></tr></tbody></table><hr><h3 id="🔵-blue" tabindex="-1">🔵 Blue <a class="header-anchor" href="#🔵-blue" aria-label="Permalink to &quot;🔵 Blue&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Swatch</th><th>CSS Variable</th><th>Hex</th><th>Notes</th></tr></thead><tbody><tr><td><img src="https://placehold.co/20x20/002241/002241.png" alt=""></td><td><code>--lcards-blue-darkest</code> / <code>-05</code></td><td><code>#002241</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/082b48/082b48.png" alt=""></td><td><code>--lcards-blue-10</code></td><td><code>#082b48</code></td><td>Computed (interpolated)</td></tr><tr><td><img src="https://placehold.co/20x20/1c3c55/1c3c55.png" alt=""></td><td><code>--lcards-blue-dark</code> / <code>-20</code></td><td><code>#1c3c55</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/2a7193/2a7193.png" alt=""></td><td><code>--lcards-blue-medium-dark</code> / <code>-30</code></td><td><code>#2a7193</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/37a6d1/37a6d1.png" alt=""></td><td><code>--lcards-blue</code> / <code>-medium</code> / <code>-40</code></td><td><code>#37a6d1</code></td><td>Canon (base blue)</td></tr><tr><td><img src="https://placehold.co/20x20/48b2db/48b2db.png" alt=""></td><td><code>--lcards-blue-50</code></td><td><code>#48b2db</code></td><td>Computed (interpolated)</td></tr><tr><td><img src="https://placehold.co/20x20/58bee6/58bee6.png" alt=""></td><td><code>--lcards-blue-60</code></td><td><code>#58bee6</code></td><td>Computed (interpolated)</td></tr><tr><td><img src="https://placehold.co/20x20/67caf0/67caf0.png" alt=""></td><td><code>--lcards-blue-medium-light</code> / <code>-70</code></td><td><code>#67caf0</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/93e1ff/93e1ff.png" alt=""></td><td><code>--lcards-blue-light</code> / <code>-80</code></td><td><code>#93e1ff</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/00eeee/00eeee.png" alt=""></td><td><code>--lcards-blue-lightest</code> / <code>-90</code></td><td><code>#00eeee</code></td><td>Canon: electric cyan-teal accent, <strong>not</strong> a smooth continuation of the ramp (see Shade Scale note below)</td></tr><tr><td><img src="https://placehold.co/20x20/44ffff/44ffff.png" alt=""></td><td><code>--lcards-blue-95</code></td><td><code>#44ffff</code></td><td>Computed (extrapolated, neon/electric method; see note below)</td></tr></tbody></table><hr><h3 id="🟢-green" tabindex="-1">🟢 Green <a class="header-anchor" href="#🟢-green" aria-label="Permalink to &quot;🟢 Green&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Swatch</th><th>CSS Variable</th><th>Hex</th><th>Notes</th></tr></thead><tbody><tr><td><img src="https://placehold.co/20x20/0c2a15/0c2a15.png" alt=""></td><td><code>--lcards-green-darkest</code> / <code>-05</code></td><td><code>#0c2a15</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/0b2e16/0b2e16.png" alt=""></td><td><code>--lcards-green-10</code></td><td><code>#0b2e16</code></td><td>Computed (interpolated)</td></tr><tr><td><img src="https://placehold.co/20x20/083717/083717.png" alt=""></td><td><code>--lcards-green-dark</code> / <code>-20</code></td><td><code>#083717</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/095320/095320.png" alt=""></td><td><code>--lcards-green-medium-dark</code> / <code>-30</code></td><td><code>#095320</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/266239/266239.png" alt=""></td><td><code>--lcards-green</code> / <code>-medium</code> / <code>-40</code></td><td><code>#266239</code></td><td>Canon (base green)</td></tr><tr><td><img src="https://placehold.co/20x20/306d43/306d43.png" alt=""></td><td><code>--lcards-green-50</code></td><td><code>#306d43</code></td><td>Computed (interpolated)</td></tr><tr><td><img src="https://placehold.co/20x20/3b784e/3b784e.png" alt=""></td><td><code>--lcards-green-60</code></td><td><code>#3b784e</code></td><td>Computed (interpolated)</td></tr><tr><td><img src="https://placehold.co/20x20/458359/458359.png" alt=""></td><td><code>--lcards-green-medium-light</code> / <code>-70</code></td><td><code>#458359</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/80bb93/80bb93.png" alt=""></td><td><code>--lcards-green-light</code> / <code>-80</code></td><td><code>#80bb93</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/b8e0c1/b8e0c1.png" alt=""></td><td><code>--lcards-green-lightest</code> / <code>-90</code></td><td><code>#b8e0c1</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/cdf6d6/cdf6d6.png" alt=""></td><td><code>--lcards-green-95</code></td><td><code>#cdf6d6</code></td><td>Computed (extrapolated)</td></tr></tbody></table><hr><h3 id="🟡-yellow" tabindex="-1">🟡 Yellow <a class="header-anchor" href="#🟡-yellow" aria-label="Permalink to &quot;🟡 Yellow&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Swatch</th><th>CSS Variable</th><th>Hex</th><th>Notes</th></tr></thead><tbody><tr><td><img src="https://placehold.co/20x20/70602c/70602c.png" alt=""></td><td><code>--lcards-yellow-darkest</code> / <code>-05</code></td><td><code>#70602c</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/847131/847131.png" alt=""></td><td><code>--lcards-yellow-10</code></td><td><code>#847131</code></td><td>Computed (interpolated)</td></tr><tr><td><img src="https://placehold.co/20x20/ac943b/ac943b.png" alt=""></td><td><code>--lcards-yellow-dark</code> / <code>-20</code></td><td><code>#ac943b</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/d2bf50/d2bf50.png" alt=""></td><td><code>--lcards-yellow-medium-dark</code> / <code>-30</code></td><td><code>#d2bf50</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/f9ef97/f9ef97.png" alt=""></td><td><code>--lcards-yellow</code> / <code>-medium</code> / <code>-40</code></td><td><code>#f9ef97</code></td><td>Canon (base yellow)</td></tr><tr><td><img src="https://placehold.co/20x20/fbf3a8/fbf3a8.png" alt=""></td><td><code>--lcards-yellow-50</code></td><td><code>#fbf3a8</code></td><td>Computed (interpolated)</td></tr><tr><td><img src="https://placehold.co/20x20/fdf6b9/fdf6b9.png" alt=""></td><td><code>--lcards-yellow-60</code></td><td><code>#fdf6b9</code></td><td>Computed (interpolated)</td></tr><tr><td><img src="https://placehold.co/20x20/fffac9/fffac9.png" alt=""></td><td><code>--lcards-yellow-medium-light</code> / <code>-70</code></td><td><code>#fffac9</code></td><td>Canon</td></tr><tr><td><img src="https://placehold.co/20x20/e7e6de/e7e6de.png" alt=""></td><td><code>--lcards-yellow-light</code> / <code>-80</code></td><td><code>#e7e6de</code></td><td>Canon: desaturates toward beige, <strong>not</strong> a smooth continuation of the ramp (see Shade Scale note below)</td></tr><tr><td><img src="https://placehold.co/20x20/f5f5dc/f5f5dc.png" alt=""></td><td><code>--lcards-yellow-lightest</code> / <code>-90</code></td><td><code>#f5f5dc</code></td><td>Canon: warm white / cream</td></tr><tr><td><img src="https://placehold.co/20x20/fbfbe2/fbfbe2.png" alt=""></td><td><code>--lcards-yellow-95</code></td><td><code>#fbfbe2</code></td><td>Computed (extrapolated)</td></tr></tbody></table><hr><h3 id="shade-scale" tabindex="-1">Shade Scale <a class="header-anchor" href="#shade-scale" aria-label="Permalink to &quot;Shade Scale&quot;">​</a></h3><p>Each colour family carries <strong>two parallel naming schemes</strong> for the same 11-stop scale, which lines up 1:1 with Home Assistant&#39;s own <code>--ha-color-&lt;family&gt;-&lt;tone&gt;</code> tonal system (<code>05</code>/<code>10</code>/<code>20</code>/<code>30</code>/<code>40</code>/<code>50</code>/<code>60</code>/<code>70</code>/<code>80</code>/<code>90</code>/<code>95</code>):</p><table tabindex="0"><thead><tr><th>Named shade</th><th>Numeric tone</th><th>Description</th><th>Origin</th></tr></thead><tbody><tr><td><code>-darkest</code></td><td><code>-05</code></td><td>Deepest / near-black tone</td><td><strong>Canon</strong>: hand-picked Picard-screen colour</td></tr><tr><td><em>(none: numeric only)</em></td><td><code>-10</code></td><td></td><td>Computed: interpolated between <code>-05</code> and <code>-20</code></td></tr><tr><td><code>-dark</code></td><td><code>-20</code></td><td>Dark variant</td><td><strong>Canon</strong></td></tr><tr><td><code>-medium-dark</code></td><td><code>-30</code></td><td>Between dark and mid</td><td><strong>Canon</strong></td></tr><tr><td><em>(base / <code>-medium</code>)</em></td><td><code>-40</code></td><td>Core reference colour: <code>--lcards-&lt;colour&gt;</code>, <code>--lcards-&lt;colour&gt;-medium</code>, and <code>--lcards-&lt;colour&gt;-40</code> all resolve to the same value</td><td><strong>Canon</strong></td></tr><tr><td><em>(none: numeric only)</em></td><td><code>-50</code></td><td></td><td>Computed: interpolated between <code>-40</code> and <code>-70</code></td></tr><tr><td><em>(none: numeric only)</em></td><td><code>-60</code></td><td></td><td>Computed: interpolated between <code>-40</code> and <code>-70</code></td></tr><tr><td><code>-medium-light</code></td><td><code>-70</code></td><td>Between mid and light</td><td><strong>Canon</strong></td></tr><tr><td><code>-light</code></td><td><code>-80</code></td><td>Light variant</td><td><strong>Canon</strong></td></tr><tr><td><code>-lightest</code></td><td><code>-90</code></td><td>Palest tone at the original 7-stop scale</td><td><strong>Canon</strong></td></tr><tr><td><em>(none: numeric only)</em></td><td><code>-95</code></td><td>Lightest of all</td><td>Computed: extrapolated beyond <code>-90</code> using a neon/electric method (holds hue and chroma from <code>-lightest</code>, only lightness moves toward white, chosen over a fade-to-white approach because LCARS palettes read as vibrant even at their palest steps)</td></tr></tbody></table><p><strong>The 7 named/canon stops (<code>-darkest</code> through <code>-lightest</code>) are the original, hand-authored Picard-screen colours and are never altered.</strong> The 4 numeric-only stops (<code>-10</code>, <code>-50</code>, <code>-60</code>, <code>-95</code>) were added later, computed in OKLCH colour space and anchored to the canon values, purely to give Home Assistant&#39;s own semantic colour system (<code>--ha-color-*</code>) the same 11-stop resolution it expects; see <a href="./../../development/ha-css-vars.html#layer-1-colour-palette-atoms">ha-css-vars.md</a> for how these feed the HA-LCARS Picard theme profiles. Generated by <code>scripts/generate-lcards-palette-scale.js</code>.</p><p>Not every family&#39;s canon stops form a perfectly smooth ramp: blue&#39;s <code>-lightest</code> is a deliberately vibrant electric-cyan accent rather than a pale tint, and yellow&#39;s <code>-light</code>/<code>-lightest</code> desaturate toward a parchment/beige tone. These are original design choices in the canon palette, not artifacts of the computed stops.</p><blockquote><p>Gray also includes <code>--lcards-moonlight</code>, a near-white warm gray used for text, labels, and chart axes (not part of the 11-stop scale).</p></blockquote><hr><h3 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h3><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* Direct reference */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">color: var(--lcards-blue-light);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* Prefer HA-LCARS theme variable, fall back to lcards palette */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">color: var(--lcars-orange, var(--lcards-orange-medium));</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* With hex fallback */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">color: var(--lcards-orange-medium, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">#ff6753</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><hr><h2 id="ha-lcars-theme-profiles" tabindex="-1">HA-LCARS Theme Profiles <a class="header-anchor" href="#ha-lcars-theme-profiles" aria-label="Permalink to &quot;HA-LCARS Theme Profiles&quot;">​</a></h2><p>HA-LCARS includes two LCARdS theme profiles that use the <code>--lcards-*</code> palette as the single source of truth. They remap both the HA-LCARS chrome variables and the HA core colour tokens (<code>--ha-color-*</code>) so that stock HA components, LCARdS cards, and the HA-LCARS chrome all share the same palette, including alert-mode hue rotations.</p><p>→ <a href="./../../configuration/ha-lcars-theme-profiles.html">HA-LCARS Theme Profiles</a></p>`,49)])])}const m=e(c,[["render",r]]);export{g as __pageData,m as default};
